148	class TreemapView extends ChartView {
149	
150	    static type = 'treemap';
151	    type = TreemapView.type;
152	
153	    private _containerGroup: graphic.Group;
154	    private _breadcrumb: Breadcrumb;
155	    private _controller: RoamController;
156	
157	    private _oldTree: Tree;
158	
159	    private _state: 'ready' | 'animating' = 'ready';
160	
161	    private _storage = createStorage() as RenderElementStorage;
162	
163	    seriesModel: TreemapSeriesModel;
164	    api: ExtensionAPI;
165	    ecModel: GlobalModel;
166	
167	    /**
168	     * @override
169	     */
170	    render(
171	        seriesModel: TreemapSeriesModel,
172	        ecModel: GlobalModel,
173	        api: ExtensionAPI,
174	        payload: TreemapZoomToNodePayload | TreemapRenderPayload | TreemapMovePayload | TreemapRootToNodePayload
175	    ) {
176	
177	        const models = ecModel.findComponents({
178	            mainType: 'series', subType: 'treemap', query: payload
179	        });
180	        if (indexOf(models, seriesModel) < 0) {
181	            return;
182	        }
183	
184	        this.seriesModel = seriesModel;
185	        this.api = api;
186	        this.ecModel = ecModel;
187	
188	        const types = ['treemapZoomToNode', 'treemapRootToNode'];
189	        const targetInfo = helper
190	            .retrieveTargetInfo(payload, types, seriesModel);
191	        const payloadType = payload && payload.type;
192	        const layoutInfo = seriesModel.layoutInfo;
193	        const isInit = !this._oldTree;
194	        const thisStorage = this._storage;
195	
196	        // Mark new root when action is treemapRootToNode.
197	        const reRoot = (payloadType === 'treemapRootToNode' && targetInfo && thisStorage)
198	            ? {
199	                rootNodeGroup: thisStorage.nodeGroup[targetInfo.node.getRawIndex()],
200	                direction: (payload as TreemapRootToNodePayload).direction
201	            }
202	            : null;
203	
204	        const containerGroup = this._giveContainerGroup(layoutInfo);
205	        const hasAnimation = seriesModel.get('animation');
206	
207	        const renderResult = this._doRender(containerGroup, seriesModel, reRoot);
208	        (
209	            hasAnimation && !isInit && (
210	                !payloadType
211	                || payloadType === 'treemapZoomToNode'
212	                || payloadType === 'treemapRootToNode'
213	            )
214	        )
215	            ? this._doAnimation(containerGroup, renderResult, seriesModel, reRoot)
216	            : renderResult.renderFinally();
217	
218	        this._resetController(api);
219	
220	        this._renderBreadcrumb(seriesModel, api, targetInfo);
221	    }
