223	    private _giveContainerGroup(layoutInfo: LayoutRect) {
224	        let containerGroup = this._containerGroup;
225	        if (!containerGroup) {
226	            // FIXME
227	            // 加一层containerGroup是为了clip，但是现在clip功能并没有实现。
228	            containerGroup = this._containerGroup = new Group();
229	            this._initEvents(containerGroup);
230	            this.group.add(containerGroup);
231	        }
232	        containerGroup.x = layoutInfo.x;
233	        containerGroup.y = layoutInfo.y;
234	
235	        return containerGroup;
236	    }
