238	    private _doRender(containerGroup: graphic.Group, seriesModel: TreemapSeriesModel, reRoot: ReRoot): RenderResult {
239	        const thisTree = seriesModel.getData().tree;
240	        const oldTree = this._oldTree;
241	
242	        // Clear last shape records.
243	        const lastsForAnimation = createStorage() as LastCfgStorage;
244	        const thisStorage = createStorage() as RenderElementStorage;
245	        const oldStorage = this._storage;
246	        const willInvisibleEls: RenderResult['willInvisibleEls'] = [];
247	
248	        function doRenderNode(thisNode: TreeNode, oldNode: TreeNode, parentGroup: graphic.Group, depth: number) {
249	            return renderNode(
250	                seriesModel,
251	                thisStorage, oldStorage, reRoot,
252	                lastsForAnimation, willInvisibleEls,
253	                thisNode, oldNode, parentGroup, depth
254	            );
255	        }
256	
257	        // Notice: When thisTree and oldTree are the same tree (see list.cloneShallow),
258	        // the oldTree is actually losted, so we cannot find all of the old graphic
259	        // elements from tree. So we use this strategy: make element storage, move
260	        // from old storage to new storage, clear old storage.
261	
262	        dualTravel(
263	            thisTree.root ? [thisTree.root] : [],
264	            (oldTree && oldTree.root) ? [oldTree.root] : [],
265	            containerGroup,
266	            thisTree === oldTree || !oldTree,
267	            0
268	        );
269	
270	        // Process all removing.
271	        const willDeleteEls = clearStorage(oldStorage) as RenderElementStorage;
272	
273	        this._oldTree = thisTree;
274	        this._storage = thisStorage;
275	
276	        return {
277	            lastsForAnimation,
278	            willDeleteEls,
279	            renderFinally
280	        };
281	
282	        function dualTravel(
283	            thisViewChildren: TreemapLayoutNode[],
284	            oldViewChildren: TreemapLayoutNode[],
285	            parentGroup: graphic.Group,
286	            sameTree: boolean,
287	            depth: number
288	        ) {
289	            // When 'render' is triggered by action,
290	            // 'this' and 'old' may be the same tree,
291	            // we use rawIndex in that case.
292	            if (sameTree) {
293	                oldViewChildren = thisViewChildren;
294	                each(thisViewChildren, function (child, index) {
295	                    !child.isRemoved() && processNode(index, index);
296	                });
297	            }
298	            // Diff hierarchically (diff only in each subtree, but not whole).
299	            // because, consistency of view is important.
300	            else {
301	                (new DataDiffer(oldViewChildren, thisViewChildren, getKey, getKey))
302	                    .add(processNode)
303	                    .update(processNode)
304	                    .remove(curry(processNode, null))
305	                    .execute();
306	            }
307	
308	            function getKey(node: TreeNode) {
309	                // Identify by name or raw index.
310	                return node.getId();
311	            }
312	
313	            function processNode(newIndex: number, oldIndex?: number) {
314	                const thisNode = newIndex != null ? thisViewChildren[newIndex] : null;
315	                const oldNode = oldIndex != null ? oldViewChildren[oldIndex] : null;
316	
317	                const group = doRenderNode(thisNode, oldNode, parentGroup, depth);
318	
319	                group && dualTravel(
320	                    thisNode && thisNode.viewChildren || [],
321	                    oldNode && oldNode.viewChildren || [],
322	                    group,
323	                    sameTree,
324	                    depth + 1
325	                );
326	            }
327	        }
328	
329	        function clearStorage(storage: RenderElementStorage) {
330	            const willDeleteEls = createStorage() as RenderElementStorage;
331	            storage && each(storage, function (store, storageName) {
332	                const delEls = willDeleteEls[storageName];
333	                each(store, function (el) {
334	                    el && (delEls.push(el as any), inner(el).willDelete = true);
335	                });
336	            });
337	            return willDeleteEls;
338	        }
339	
340	        function renderFinally() {
341	            each(willDeleteEls, function (els) {
342	                each(els, function (el) {
343	                    el.parent && el.parent.remove(el);
344	                });
345	            });
346	            each(willInvisibleEls, function (el) {
347	                el.invisible = true;
348	                // Setting invisible is for optimizing, so no need to set dirty,
349	                // just mark as invisible.
350	                el.dirty();
351	            });
352	        }
353	    }
354	
355	    private _doAnimation(
356	        containerGroup: graphic.Group,
357	        renderResult: RenderResult,
358	        seriesModel: TreemapSeriesModel,
359	        reRoot: ReRoot
360	    ) {
361	        const durationOption = seriesModel.get('animationDurationUpdate');
362	        const easingOption = seriesModel.get('animationEasing');
363	        // TODO: do not support function until necessary.
364	        const duration = (isFunction(durationOption) ? 0 : durationOption) || 0;
365	        const easing = (isFunction(easingOption) ? null : easingOption) || 'cubicOut';
366	        const animationWrap = animationUtil.createWrap();
367	
368	        // Make delete animations.
369	        each(renderResult.willDeleteEls, function (store, storageName) {
370	            each(store, function (el, rawIndex) {
371	                if ((el as Displayable).invisible) {
372	                    return;
373	                }
374	
375	                const parent = el.parent; // Always has parent, and parent is nodeGroup.
376	                let target: PathProps;
377	                const innerStore = inner(parent);
378	
379	                if (reRoot && reRoot.direction === 'drillDown') {
380	                    target = parent === reRoot.rootNodeGroup
381	                        // This is the content element of view root.
382	                        // Only `content` will enter this branch, because
383	                        // `background` and `nodeGroup` will not be deleted.
384	                        ? {
385	                            shape: {
386	                                x: 0,
387	                                y: 0,
388	                                width: innerStore.nodeWidth,
389	                                height: innerStore.nodeHeight
390	                            },
391	                            style: {
392	                                opacity: 0
393	                            }
394	                        }
395	                        // Others.
396	                        : {style: {opacity: 0}};
397	                }
398	                else {
399	                    let targetX = 0;
400	                    let targetY = 0;
401	
402	                    if (!innerStore.willDelete) {
403	                        // Let node animate to right-bottom corner, cooperating with fadeout,
404	                        // which is appropriate for user understanding.
405	                        // Divided by 2 for reRoot rolling up effect.
406	                        targetX = innerStore.nodeWidth / 2;
407	                        targetY = innerStore.nodeHeight / 2;
408	                    }
409	
410	                    target = storageName === 'nodeGroup'
411	                        ? {x: targetX, y: targetY, style: {opacity: 0}}
412	                        : {
413	                            shape: {x: targetX, y: targetY, width: 0, height: 0},
414	                            style: {opacity: 0}
415	                        };
416	                }
417	
418	                // TODO: do not support delay until necessary.
419	                target && animationWrap.add(el, target, duration, 0, easing);
420	            });
421	        });
422	
423	        // Make other animations
424	        each(this._storage, function (store, storageName) {
425	            each(store, function (el, rawIndex) {
426	                const last = renderResult.lastsForAnimation[storageName][rawIndex];
427	                const target: PathProps = {};
428	
429	                if (!last) {
430	                    return;
431	                }
432	
433	                if (el instanceof graphic.Group) {
434	                    if (last.oldX != null) {
435	                        target.x = el.x;
436	                        target.y = el.y;
437	                        el.x = last.oldX;
438	                        el.y = last.oldY;
439	                    }
440	                }
441	                else {
442	                    if (last.oldShape) {
443	                        target.shape = extend({}, el.shape);
444	                        el.setShape(last.oldShape);
445	                    }
446	
447	                    if (last.fadein) {
448	                        el.setStyle('opacity', 0);
449	                        target.style = {opacity: 1};
450	                    }
451	                    // When animation is stopped for succedent animation starting,
452	                    // el.style.opacity might not be 1
453	                    else if (el.style.opacity !== 1) {
454	                        target.style = {opacity: 1};
455	                    }
456	                }
457	
458	                animationWrap.add(el, target, duration, 0, easing);
459	            });
460	        }, this);
461	
462	        this._state = 'animating';
463	
464	        animationWrap
465	            .finished(bind(function () {
466	                this._state = 'ready';
467	                renderResult.renderFinally();
468	            }, this))
469	            .start();
470	    }
