472	    private _resetController(api: ExtensionAPI) {
473	        let controller = this._controller;
474	
475	        // Init controller.
476	        if (!controller) {
477	            controller = this._controller = new RoamController(api.getZr());
478	            controller.enable(this.seriesModel.get('roam'));
479	            controller.on('pan', bind(this._onPan, this));
480	            controller.on('zoom', bind(this._onZoom, this));
481	        }
482	
483	        const rect = new BoundingRect(0, 0, api.getWidth(), api.getHeight());
484	        controller.setPointerChecker(function (e, x, y) {
485	            return rect.contain(x, y);
486	        });
487	    }
