497	    private _onPan(e: RoamEventParams['pan']) {
498	        if (this._state !== 'animating'
499	            && (Math.abs(e.dx) > DRAG_THRESHOLD || Math.abs(e.dy) > DRAG_THRESHOLD)
500	        ) {
501	            // These param must not be cached.
502	            const root = this.seriesModel.getData().tree.root;
503	
504	            if (!root) {
505	                return;
506	            }
507	
508	            const rootLayout = root.getLayout();
509	
510	            if (!rootLayout) {
511	                return;
512	            }
513	
514	            this.api.dispatchAction({
515	                type: 'treemapMove',
516	                from: this.uid,
517	                seriesId: this.seriesModel.id,
518	                rootRect: {
519	                    x: rootLayout.x + e.dx, y: rootLayout.y + e.dy,
520	                    width: rootLayout.width, height: rootLayout.height
521	                }
522	            } as TreemapMovePayload);
523	        }
524	    }
525	
526	    private _onZoom(e: RoamEventParams['zoom']) {
527	        let mouseX = e.originX;
528	        let mouseY = e.originY;
529	
530	        if (this._state !== 'animating') {
531	            // These param must not be cached.
532	            const root = this.seriesModel.getData().tree.root;
533	
534	            if (!root) {
535	                return;
536	            }
537	
538	            const rootLayout = root.getLayout();
539	
540	            if (!rootLayout) {
541	                return;
542	            }
543	
544	            const rect = new BoundingRect(
545	                rootLayout.x, rootLayout.y, rootLayout.width, rootLayout.height
546	            );
547	            const layoutInfo = this.seriesModel.layoutInfo;
548	
549	            // Transform mouse coord from global to containerGroup.
550	            mouseX -= layoutInfo.x;
551	            mouseY -= layoutInfo.y;
552	
553	            // Scale root bounding rect.
554	            const m = matrix.create();
555	            matrix.translate(m, m, [-mouseX, -mouseY]);
556	            matrix.scale(m, m, [e.scale, e.scale]);
557	            matrix.translate(m, m, [mouseX, mouseY]);
558	
559	            rect.applyTransform(m);
560	
561	            this.api.dispatchAction({
562	                type: 'treemapRender',
563	                from: this.uid,
564	                seriesId: this.seriesModel.id,
565	                rootRect: {
566	                    x: rect.x, y: rect.y,
567	                    width: rect.width, height: rect.height
568	                }
569	            } as TreemapRenderPayload);
570	        }
571	    }
