573	    private _initEvents(containerGroup: graphic.Group) {
574	        containerGroup.on('click', (e) => {
575	            if (this._state !== 'ready') {
576	                return;
577	            }
578	
579	            const nodeClick = this.seriesModel.get('nodeClick', true);
580	
581	            if (!nodeClick) {
582	                return;
583	            }
584	
585	            const targetInfo = this.findTarget(e.offsetX, e.offsetY);
586	
587	            if (!targetInfo) {
588	                return;
589	            }
590	
591	            const node = targetInfo.node;
592	            if (node.getLayout().isLeafRoot) {
593	                this._rootToNode(targetInfo);
594	            }
595	            else {
596	                if (nodeClick === 'zoomToNode') {
597	                    this._zoomToNode(targetInfo);
598	                }
599	                else if (nodeClick === 'link') {
600	                    const itemModel = node.hostTree.data.getItemModel<TreeSeriesNodeItemOption>(node.dataIndex);
601	                    const link = itemModel.get('link', true);
602	                    const linkTarget = itemModel.get('target', true) || 'blank';
603	                    link && windowOpen(link, linkTarget);
604	                }
605	            }
606	
607	        }, this);
608	    }
