610	    private _renderBreadcrumb(seriesModel: TreemapSeriesModel, api: ExtensionAPI, targetInfo: FoundTargetInfo) {
611	        if (!targetInfo) {
612	            targetInfo = seriesModel.get('leafDepth', true) != null
613	                ? {node: seriesModel.getViewRoot()}
614	                // FIXME
615	                // better way?
616	                // Find breadcrumb tail on center of containerGroup.
617	                : this.findTarget(api.getWidth() / 2, api.getHeight() / 2);
618	
619	            if (!targetInfo) {
620	                targetInfo = {node: seriesModel.getData().tree.root};
621	            }
622	        }
623	
624	        (this._breadcrumb || (this._breadcrumb = new Breadcrumb(this.group)))
625	            .render(seriesModel, api, targetInfo.node, (node) => {
626	                if (this._state !== 'animating') {
627	                    helper.aboveViewRoot(seriesModel.getViewRoot(), node)
628	                        ? this._rootToNode({node: node})
629	                        : this._zoomToNode({node: node});
630	                }
631	            });
632	    }
