649	    private _zoomToNode(targetInfo: FoundTargetInfo) {
650	        this.api.dispatchAction({
651	            type: 'treemapZoomToNode',
652	            from: this.uid,
653	            seriesId: this.seriesModel.id,
654	            targetNode: targetInfo.node
655	        });
