658	    private _rootToNode(targetInfo: FoundTargetInfo) {
659	        this.api.dispatchAction({
660	            type: 'treemapRootToNode',
661	            from: this.uid,
662	            seriesId: this.seriesModel.id,
663	            targetNode: targetInfo.node
664	        });
665	    }
666	
667	    /**
668	     * @public
669	     * @param {number} x Global coord x.
670	     * @param {number} y Global coord y.
671	     * @return {Object} info If not found, return undefined;
672	     * @return {number} info.node Target node.
673	     * @return {number} info.offsetX x refer to target node.
674	     * @return {number} info.offsetY y refer to target node.
675	     */
676	    findTarget(x: number, y: number): FoundTargetInfo {
677	        let targetInfo;
